/* Corridors sampled for travel time.
 *
 * Each junction is described once, by the four points where its arms are
 * sampled.  Every arm has that point twice, because these roads are divided:
 * `in` sits on the carriageway that APPROACHES the junction, `out` on the one
 * that LEAVES it.  Getting that pair the wrong way round is what made TomTom
 * route SN over 892 m and EW over 664 m when the straight drive is ~400 m --
 * it was sending the car up to a U-turn gap and back, and those two movements
 * could not be compared against the model at all.
 *
 * Two further guards against the same failure:
 *   - every route is forced through `centre`, so it cannot go around the block;
 *   - every route carries `heading`, the compass direction the vehicle is
 *     already travelling at the origin, so it cannot open with a U-turn.
 *
 * `expected_m` is what the drive should measure if it goes the direct way.
 * Compare it against the returned lengthInMeters: a ratio much above 1 means
 * the route detoured and that row is not measuring the movement it claims to.
 */

const JUNCTIONS = {
  indiranagar_cmh: {
    centre: '12.9784417,77.6409480',
    arms: {
      // out taken off the northbound polyline TomTom returned, not derived:
      // the northbound lanes sit at lon 77.64070 at +200 m, while both
      // coordinates tried before (77.64104, 77.64086) were 25-35 m east of
      // them, on the southbound carriageway.  Arrival was heading SOUTH.
      N: { in: '12.9802403,77.6410403', out: '12.98024,77.64070' },
      S: { in: '12.9766431,77.6408557', out: '12.9766431,77.6410403' },
      E: { in: '12.9783518,77.6427938', out: '12.9785316,77.6427938' },
      // out off the westbound polyline: westbound lanes sit at lat 12.97824
      // by lon 77.63910, eastbound at 12.97834-12.97836.  The old value
      // (12.97835) was eastbound, so EW and SW drove 125 m past it, turned,
      // and came back east.  Same fault the N arm had.
      W: { in: '12.9785316,77.6391022', out: '12.97824,77.63910' },
    },
    // Only the modelled junction samples turns; see the note on quota below.
    turns: true,
  },
  ejipura: {
    centre: '12.9386370,77.6338840',
    arms: {
      N: { in: '12.9404356,77.6334763', out: '12.9404356,77.6332917' },
      S: { in: '12.9368384,77.6332917', out: '12.9368384,77.6334763' },
      E: { in: '12.9385471,77.6352295', out: '12.9387269,77.6352295' },
      W: { in: '12.9387269,77.6315385', out: '12.9385471,77.6315385' },
    },
    turns: false,
  },
  sonyworld: {
    centre: '12.9366906,77.6264514',
    arms: {
      N: { in: '12.9384892,77.6265437', out: '12.9384892,77.6263591' },
      S: { in: '12.934892,77.6263591',  out: '12.934892,77.6265437'  },
      E: { in: '12.9366007,77.6282969', out: '12.9367805,77.6282969' },
      W: { in: '12.9367805,77.6246059', out: '12.9366007,77.6246059' },
    },
    turns: false,
  },
};

const THROUGH = [['N','S'], ['S','N'], ['E','W'], ['W','E']];
const TURNS   = [['N','E'], ['N','W'], ['S','E'], ['S','W'],
                 ['E','N'], ['E','S'], ['W','N'], ['W','S']];

const rad = (d) => (d * Math.PI) / 180;
const parse = (s) => s.split(',').map(Number);

/* Compass bearing in degrees, 0 = true north, clockwise. */
function bearing(from, to) {
  const [lat1, lon1] = parse(from);
  const [lat2, lon2] = parse(to);
  const p1 = rad(lat1), p2 = rad(lat2), dl = rad(lon2 - lon1);
  const y = Math.sin(dl) * Math.cos(p2);
  const x = Math.cos(p1) * Math.sin(p2) - Math.sin(p1) * Math.cos(p2) * Math.cos(dl);
  return Math.round((Math.atan2(y, x) * 180 / Math.PI + 360) % 360) % 360;
}

/* Great-circle metres between two "lat,lon" strings. */
function metres(from, to) {
  const [lat1, lon1] = parse(from);
  const [lat2, lon2] = parse(to);
  const R = 6371000;
  const p1 = rad(lat1), p2 = rad(lat2);
  const dp = rad(lat2 - lat1), dl = rad(lon2 - lon1);
  const h = Math.sin(dp / 2) ** 2 + Math.cos(p1) * Math.cos(p2) * Math.sin(dl / 2) ** 2;
  return Math.round(2 * R * Math.asin(Math.sqrt(h)));
}

const out = [];
for (const [junction, spec] of Object.entries(JUNCTIONS)) {
  const pairs = spec.turns ? THROUGH.concat(TURNS) : THROUGH;
  for (const [from, to] of pairs) {
    const orig = spec.arms[from].in;
    const dest = spec.arms[to].out;
    const via  = spec.centre;
    out.push({ json: {
      move_id: junction + '_' + from + to,
      junction,
      movement: from + to,
      movement_kind: THROUGH.some((p) => p[0] === from && p[1] === to) ? 'through' : 'turn',
      from_arm: from,
      to_arm: to,
      orig, dest, via,
      // Heading on the first leg, so TomTom departs the way the traffic does.
      heading: bearing(orig, via),
      // Direct road distance: in to the junction, then out again.
      expected_m: metres(orig, via) + metres(via, dest),
    }});
  }
}
return out;

