const source = $('Set Points').all();
const output = [];

for (const item of $input.all()) {
  const srcIdx = item.pairedItem && typeof item.pairedItem.item === 'number' ? item.pairedItem.item : 0;
  const src = source[srcIdx] ? source[srcIdx].json : {};
  const body = item.json || {};
  const now = DateTime.now();

  let lengthInMeters = null, travelTimeInSeconds = null, historicTravelTimeInSeconds = null,
      noTrafficTravelTimeInSeconds = null, trafficDelayInSeconds = null, departureTime = null,
      errorMsg = null, httpStatus = 200;

  if (body.routes && body.routes[0] && body.routes[0].summary) {
    const s = body.routes[0].summary;
    lengthInMeters = s.lengthInMeters;
    travelTimeInSeconds = s.travelTimeInSeconds;
    historicTravelTimeInSeconds = s.historicTrafficTravelTimeInSeconds;
    noTrafficTravelTimeInSeconds = s.noTrafficTravelTimeInSeconds;
    trafficDelayInSeconds = s.trafficDelayInSeconds;
    departureTime = s.departureTime;
  } else {
    errorMsg = 'no summary (status null) :: ' + JSON.stringify(body).slice(0, 250);
    httpStatus = null;
  }

  // A route that comes back much longer than the direct drive did not measure
  // the movement it claims to -- it went around the median.  That is exactly
  // how SN and EW quietly became uncomparable, and it was only caught by hand
  // weeks later.  Record it on the row so the next one is caught on arrival.
  const expected_m = src.expected_m || null;
  const detour_ratio = (expected_m && lengthInMeters)
    ? Math.round((lengthInMeters / expected_m) * 100) / 100
    : null;
  const route_ok = detour_ratio === null ? null : detour_ratio <= 1.25;
  if (route_ok === false && !errorMsg) {
    errorMsg = 'detour: route is ' + detour_ratio + 'x the direct drive ('
             + lengthInMeters + ' m vs ' + expected_m + ' m expected)';
  }

  output.push({ json: {
    move_id: src.move_id,
    junction: src.junction,
    movement: src.movement,
    movement_kind: src.movement_kind,
    from_arm: src.from_arm,
    to_arm: src.to_arm,
    orig: src.orig,
    dest: src.dest,
    via: src.via,
    heading: src.heading,
    observed_utc: now.toUTC().toISO({ suppressMilliseconds: true }),
    observed_ist: now.setZone('Asia/Kolkata').toISO({ suppressMilliseconds: true }),
    lengthInMeters, expected_m, detour_ratio, route_ok,
    travelTimeInSeconds, historicTravelTimeInSeconds,
    noTrafficTravelTimeInSeconds, trafficDelayInSeconds, departureTime,
    error: errorMsg, http_status: httpStatus
  }});
}
return output;

const source = $('Set Flow Points').all();
const output = [];

for (const item of $input.all()) {
  const srcIdx = item.pairedItem && typeof item.pairedItem.item === 'number' ? item.pairedItem.item : 0;
  const src = source[srcIdx] ? source[srcIdx].json : {};
  const body = (item.json && item.json.flowSegmentData) || null;
  const now = DateTime.now();

  let currentSpeed = null, freeFlowSpeed = null, currentTravelTime = null,
      freeFlowTravelTime = null, confidence = null, roadClosure = null,
      frc = null, errorMsg = null;

  if (body) {
    currentSpeed = body.currentSpeed;
    freeFlowSpeed = body.freeFlowSpeed;
    currentTravelTime = body.currentTravelTime;
    freeFlowTravelTime = body.freeFlowTravelTime;
    confidence = body.confidence;
    roadClosure = body.roadClosure;
    frc = body.frc;
  } else {
    errorMsg = 'no flowSegmentData :: ' + JSON.stringify(item.json).slice(0, 250);
  }

  output.push({ json: {
    move_id: src.move_id, junction: src.junction, movement: src.movement,
    point: src.orig,
    fetched_at_utc: now.toUTC().toISO({ suppressMilliseconds: true }),
    fetched_at_ist: now.setZone('Asia/Kolkata').toISO({ suppressMilliseconds: true }),
    frc, currentSpeed, freeFlowSpeed, currentTravelTime, freeFlowTravelTime,
    confidence, roadClosure, error: errorMsg
  }});
}
return output;

