const categoryMap = {0:'Unknown',1:'Accident',2:'Fog',3:'DangerousConditions',4:'Rain',5:'Ice',6:'Jam',7:'LaneClosed',8:'RoadClosed',9:'RoadWorks',10:'Wind',11:'Flooding',14:'BrokenDownVehicle'};
const source = $('Set Junctions').all();
const output = [];
const fetchedAt = new Date().toISOString();

for (const item of $input.all()) {
  const srcIdx = item.pairedItem && typeof item.pairedItem.item === 'number' ? item.pairedItem.item : 0;
  const junction = source[srcIdx] ? source[srcIdx].json.junction : 'unknown';
  const bbox = source[srcIdx] ? source[srcIdx].json.bbox : '';

  const body = item.json || {};
  if (!body.incidents) {
    // request failed or errored - log it, don't silently drop
    output.push({ json: {
      junction, bbox, fetched_at: fetchedAt,
      incident_id: null, category: 'FETCH_ERROR', description: JSON.stringify(body).slice(0,300),
      magnitude: null, delay_seconds: null, from: null, to: null,
      start_time: null, end_time: null, road_numbers: null, lat: null, lon: null
    }});
    continue;
  }

  if (body.incidents.length === 0) {
    output.push({ json: {
      junction, bbox, fetched_at: fetchedAt,
      incident_id: null, category: 'none', description: 'No active incidents',
      magnitude: null, delay_seconds: null, from: null, to: null,
      start_time: null, end_time: null, road_numbers: null, lat: null, lon: null
    }});
    continue;
  }

  for (const inc of body.incidents) {
    const p = inc.properties || {};
    const firstEvent = (p.events && p.events[0]) || {};
    let lat = null, lon = null;
    const coords = inc.geometry && inc.geometry.coordinates;
    if (coords) {
      const pt = Array.isArray(coords[0]) ? coords[0] : coords;
      lon = pt[0]; lat = pt[1];
    }
    output.push({ json: {
      junction, bbox, fetched_at: fetchedAt,
      incident_id: p.id || null,
      category: categoryMap[p.iconCategory] !== undefined ? categoryMap[p.iconCategory] : p.iconCategory,
      description: firstEvent.description || null,
      magnitude: p.magnitudeOfDelay !== undefined ? p.magnitudeOfDelay : null,
      delay_seconds: p.delay !== undefined ? p.delay : null,
      from: p.from || null,
      to: p.to || null,
      start_time: p.startTime || null,
      end_time: p.endTime || null,
      road_numbers: (p.roadNumbers || []).join('; '),
      lat, lon
    }});
  }
}
return output;

/* Sample points for the flow-segment (free-flow speed) calls.
 *
 * This branch deliberately does NOT hang off 'Set Points'.  A flow segment is
 * a speed reading at ONE coordinate, so it needs one call per approach arm --
 * four per junction.  'Set Points' now also emits the eight turning movements
 * at indiranagar_cmh, and those reuse the same four origins, so feeding this
 * branch from there would fire the identical call three times over.
 *
 * Filtering 'Set Points' instead would be worse: 'Flatten Flow Segments' pairs
 * each response back to its source by item index, and a filter in between
 * renumbers the stream, so every reading would be labelled with the wrong
 * movement.  A separate source keeps the branch 1:1 and index-safe.
 *
 * The four origins and the movement names are exactly what this branch emitted
 * before, so the FlowSegments sheet keeps its existing shape.
 */

const ARM_ORIGIN = {
  indiranagar_cmh: {
    NS: '12.9802403,77.6410403',  // enters from N
    SN: '12.9766431,77.6408557',  // enters from S
    EW: '12.9783518,77.6427938',  // enters from E
    WE: '12.9785316,77.6391022',  // enters from W
  },
  ejipura: {
    NS: '12.9404356,77.6334763',
    SN: '12.9368384,77.6332917',
    EW: '12.9385471,77.6352295',
    WE: '12.9387269,77.6315385',
  },
  sonyworld: {
    NS: '12.9384892,77.6265437',
    SN: '12.934892,77.6263591',
    EW: '12.9366007,77.6282969',
    WE: '12.9367805,77.6246059',
  },
};

const out = [];
for (const [junction, arms] of Object.entries(ARM_ORIGIN)) {
  for (const [movement, orig] of Object.entries(arms)) {
    out.push({ json: {
      move_id: junction + '_' + movement,
      junction,
      movement,
      orig,
    }});
  }
}
return out;
